from dataclasses import dataclass
from pathlib import Path
import ast


@dataclass(slots=True, frozen=True)
class ModuleImports:
    """Immutable map of normalized module names to their exported symbol aliases."""
    modules: dict[str, list[str]]


def extract_module_symbols(tree: ast.Module) -> ModuleImports:
    """Extract all top-level import module names and their symbol aliases from an AST."""
    symbols: dict[str, list[str]] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                mod = alias.name.replace(".", "_").lstrip("__").rstrip("_")
                sym = alias.name if alias.asname is None else alias.asname
                symbols.setdefault(mod, []).append(sym)
        elif isinstance(node, ast.ImportFrom):
            mod = node.module.replace(".", "_").lstrip("__").rstrip("_")
            if node.level == 0:
                for alias in node.names:
                    sym = alias.name if alias.asname is None else alias.asname
                    symbols.setdefault(mod, []).append(sym)
    return ModuleImports(modules=symbols)
```

### Guarantees
- **Zero runtime memory overhead**: Parses pure `ast.Module` trees without executing `import` statements.
- **POSIX-safe identifiers**: Strips leading `__` and trailing `_` prefixes, preventing collision with Python reserved names.
- **Type safety**: Returns a `frozen` dataclass with `dict[str, list[str]]` mapping, guaranteeing hashable keys and immutability across multi-file symbol graphs.
